// phone-kit.js
// The same file sits in every class-11 phone folder. It does the plumbing every phone page
// needs, so sketch.js can be about the idea:
//   phoneSetup(room, extra)  joins the room as a phone. false means there is no server address
//   keepAwake()              asks the phone not to lock its screen. call it from the join tap
//   tiltNow()                { x, y } from -1 to 1. x is left to right, y is top to bottom
//   recentre()               counts the way you hold the phone right now as level
//   raiseNow()               0 when the phone lies flat, 1 when it is held upright
//   otherPhones()            the other phones in the room
//   checkMyName()            takes the lowest free number, or a new one if another phone has yours
//   footerLine()             one line about the connection, for the bottom of the screen
//   centreLines(str, y, w, h)  writes centred lines that wrap at w, the first one at y. h is the line height
//
// A laptop has no tilt sensor, so the mouse or the arrow keys stand in. Move the mouse
// across the page, or hold an arrow key.
//
// Call angleMode(DEGREES) in setup(), because the tilt comes in degrees.

const REACH = 30; // degrees of tilt that count as all the way, 1
const GREY_TEXT = '#9a9a9a';

let serverProblem = '';
let hasRealTilt = false;  // true once a phone has sent a real tilt reading
let neutralBeta = null;   // the front to back angle that counts as level
let mouseHasMoved = false;
let wakeLock = null;
let screenAwake = false;
let wantAwake = false;

// a name and a colour this phone keeps, so it is the same one each time it joins
function remembered(key, make) {
  try {
    let value = localStorage.getItem(key);
    if (!value) {
      value = String(make());
      localStorage.setItem(key, value);
    }
    return value;
  } catch (e) {
    return String(make());
  }
}
// each phone is a number, Phone 1, Phone 2 and so on: the lowest number no other phone in the room has.
// the phone keeps it, so it gets the same number back when it rejoins, if that number is still free
let myNumber = Number(remembered('class12Number', function () {
  return 0;   // 0 is no number yet. checkMyName() gives one once the phone is in the room
}));
let myName = myNumber > 0 ? 'Phone ' + myNumber : 'Phone';
let myHue = Number(remembered('class11Hue', function () {
  return Math.floor(Math.random() * 360);
}));

window.addEventListener('deviceorientation', function (e) {
  if (e.beta !== null) {
    hasRealTilt = true;
  }
});
window.addEventListener('mousemove', function () {
  mouseHasMoved = true;
});

// join the room as a phone. the address the projector's code holds carries the server and the room
function phoneSetup(room, extra) {
  textFont('system-ui');
  const fromUrl = new URLSearchParams(location.search).get('shareHost');
  const host = fromUrl || window.CLASS_SHARE_HOST || '';
  if (!host || host.indexOf('REPLACE-ME') >= 0) {
    serverProblem = 'This page has no server address. Scan the code on the big screen.';
    return false;
  }
  const me = Object.assign({ role: 'phone', name: myName, hue: myHue }, extra || {});
  return shareSetup({ host: host, room: room, me: me });
}

// ask the phone not to lock. a phone that locks leaves the room
async function keepAwake() {
  wantAwake = true;
  if (!('wakeLock' in navigator)) {
    return;
  }
  if (wakeLock && !wakeLock.released) {
    return;
  }
  try {
    wakeLock = await navigator.wakeLock.request('screen');
    screenAwake = true;
    wakeLock.addEventListener('release', function () {
      screenAwake = false;
    });
  } catch (e) {
    screenAwake = false;
  }
}
// a wake lock ends when the page is hidden. ask again when it comes back
document.addEventListener('visibilitychange', function () {
  if (document.visibilityState === 'visible' && wantAwake) {
    keepAwake();
  }
});

function recentre() {
  neutralBeta = null;
}

function tiltNow() {
  if (hasRealTilt) {
    if (neutralBeta === null) {
      neutralBeta = rotationX;
    }
    return {
      x: constrain(rotationY / REACH, -1, 1),
      y: constrain((rotationX - neutralBeta) / REACH, -1, 1)
    };
  }
  return laptopTilt();
}

// 0 when the phone lies flat, 1 when it is held upright
function raiseNow() {
  if (hasRealTilt) {
    return constrain(map(rotationX, 15, 75, 0, 1), 0, 1);
  }
  if (isMobile) {
    return 0; // a phone with no tilt readings stays quiet
  }
  const t = laptopTilt();
  return constrain(map(t.y, 1, -1, 0, 1), 0, 1);
}

// the mouse stands in for tilt on a laptop. the arrow keys win while they are held
function laptopTilt() {
  if (isMobile) {
    return { x: 0, y: 0 }; // a touch is not a mouse
  }
  let x = 0;
  let y = 0;
  if (mouseHasMoved) {
    x = constrain(map(mouseX, 0, width, -1, 1), -1, 1);
    y = constrain(map(mouseY, 0, height, -1, 1), -1, 1);
  }
  if (keyIsDown(LEFT_ARROW)) {
    x = -1;
  }
  if (keyIsDown(RIGHT_ARROW)) {
    x = 1;
  }
  if (keyIsDown(UP_ARROW)) {
    y = -1;
  }
  if (keyIsDown(DOWN_ARROW)) {
    y = 1;
  }
  return { x: x, y: y };
}

function otherPhones() {
  return guests.filter(function (g) {
    return g.role === 'phone';
  });
}

// two phones with one number are hard to tell apart. the phone that joined later picks again.
// the room gives every phone an id, so 'later' is the larger id, and only one of the two moves
function checkMyName() {
  if (!shareConnected) {
    return;
  }
  const others = otherPhones();
  const clash = others.some(function (g) {
    return g.name === me.name && String(g.id) < String(shareClientId);
  });
  if (myNumber > 0 && !clash) {
    return;
  }
  const taken = others.map(function (g) {
    return g.name;
  });
  let n = 1;
  while (taken.indexOf('Phone ' + n) >= 0) {
    n++;
  }
  myNumber = n;
  myName = 'Phone ' + n;
  me.name = myName;
  try {
    localStorage.setItem('class12Number', String(n));
  } catch (e) { /* the number just will not be kept */ }
}
// phones that join at the same moment can pick the same number, so look again every second
setInterval(checkMyName, 1000);

function footerLine() {
  if (serverProblem) {
    return serverProblem;
  }
  let line = 'Connecting';
  if (shareConnected) {
    line = 'Connected';
  } else if (shareStatus === 'error') {
    line = 'Cannot reach the server. Trying again';
  }
  if (wantAwake) {
    line += screenAwake ? '. Screen stays on' : '. Keep your screen on';
  }
  return line;
}

// centred text that wraps. the text size and colour must be set first.
// it draws lines of up to w pixels across the middle of the screen and returns how many
function centreLines(str, y, w, lineH) {
  textAlign(CENTER, BASELINE);
  const rows = String(str).split('\n');
  let drawn = 0;
  for (let r = 0; r < rows.length; r++) {
    const words = rows[r].split(' ');
    let line = '';
    for (let i = 0; i < words.length; i++) {
      const next = line ? line + ' ' + words[i] : words[i];
      if (line && textWidth(next) > w) {
        text(line, width / 2, y + drawn * lineH);
        drawn += 1;
        line = words[i];
      } else {
        line = next;
      }
    }
    text(line, width / 2, y + drawn * lineH);
    drawn += 1;
  }
  return drawn;
}

// 03 Hot Potato: Phone
// Share. One potato in the whole room. When it is on your phone, shake to throw it. The big
// screen picks who catches it. If the clock runs out while you hold it, you are burned.
//
// The rule: Share keeps only the last thing written, so only the projector writes shared, and
// this phone only sends an event when it throws.
//
// The clock: the projector tells the holder how many milliseconds are left. This phone counts
// down from there on its own clock. No two phone clocks are ever compared.
//
// Try this:
//   Hold the potato for as long as you dare. The screen goes redder as time runs out.
//   On a laptop, press the space bar or click to throw.
//   Close the page of the phone that holds it. The projector gives it to someone else.
//
// Key data:
//   shared.round        { state, holder, msLeft, turn, burnedId, burnedName }
//   shareClientId       this phone's id. it has the potato when shared.round.holder is the same
//   shareEmit('throw', { id: shareClientId })   tells the projector this phone threw
//   deviceShaken()      p5 calls this when the phone is shaken

const ROOM = 'hot-potato';

// the feel of the piece
let cooldown = 800;      // milliseconds after a throw before another counts
let shakeStrength = 25;  // how hard a shake must be. p5's own default is 30

let joined = false;
let serverOk = false;
let seen = '';           // the last round this phone has looked at
let deadline = 0;        // when time runs out, on this phone's clock
let threwAt = -9999;
let gotItAt = -9999;
let burnedAt = -9999;
let k = 1;               // one design unit for this screen

function setup() {
  createCanvas(windowWidth, windowHeight);
  lockGestures();
  angleMode(DEGREES);
  setShakeThreshold(shakeStrength);

  serverOk = phoneSetup(ROOM);
  if (serverOk) {
    // one tap asks for motion and vibration. userSetupComplete() runs after it
    enablePermissionsTap(['gyro', 'vibration'], 'Tap to join the game');
  }
}

function userSetupComplete() {
  joined = true;
  keepAwake();        // a phone that locks leaves the room
  shareConnect();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function shareReady() {
  checkMyName();
}

// the round as the projector wrote it, or nothing yet
function currentRound() {
  const r = shared.round;
  if (!joined || !shareConnected || !r) {
    return null;
  }
  return r;
}

function iHold(r) {
  return r && r.state === 'play' && r.holder === shareClientId;
}

// p5 calls this when the phone is shaken
function deviceShaken() {
  throwIt();
}

// a laptop has no shake. the space bar and a click do the same
function keyPressed() {
  if (key === ' ') {
    throwIt();
  }
}
function mousePressed() {
  if (joined && !hasRealTilt) {
    throwIt();
  }
  return false;
}

function throwIt() {
  const r = currentRound();
  if (!iHold(r) || millis() - threwAt < cooldown) {
    return;
  }
  threwAt = millis();
  shareEmit('throw', { id: shareClientId });
}

function draw() {
  k = min(width / 390, height / 700);
  const r = currentRound();
  watchTheRound(r);

  if (!serverOk) {
    background(20);
    noStroke();
    fill(255);
    textStyle(BOLD);
    textSize(26 * k);
    centreLines(serverProblem, height * 0.2, width * 0.85, 34 * k);
    textStyle(NORMAL);
    return;
  }

  if (!r) {
    background(20);
    drawWords([['03 Hot Potato', 1]]);
  } else if (r.state === 'waiting') {
    background(20);
    const n = 1 + otherPhones().length;
    const here = n === 1 ? 'You are the only phone here.' : 'You are one of ' + n + '.';
    drawWords([['Waiting for more phones', 1], ['Two phones make a game.\n' + here, 0]]);
  } else if (r.state === 'burned') {
    drawBurned(r);
  } else if (iHold(r)) {
    drawHolding();
  } else {
    drawWatching(r);
  }
  drawFooter();
}

// 1. notice a new round or a new holder. 2. start the clock again. 3. buzz.
function watchTheRound(r) {
  if (!r) {
    return;
  }
  const key = r.state + '|' + r.holder + '|' + r.turn;
  if (key === seen) {
    return;
  }
  seen = key;
  if (r.state === 'play') {
    deadline = millis() + r.msLeft;
  }
  if (iHold(r)) {
    gotItAt = millis();
    vibrate(150);                 // Android only
  }
  if (r.state === 'burned' && r.burnedId === shareClientId) {
    burnedAt = millis();
    vibrate([300, 100, 500]);
  }
}

// the potato is yours. the screen goes redder as time runs out
function drawHolding() {
  const left = max(0, (deadline - millis()) / 1000);
  const total = max(1, shared.round.msLeft / 1000);
  const heat = 1 - constrain(left / max(total, 4), 0, 1);
  background(lerpColor(color('#8a3a00'), color('#d11a1a'), heat));

  const wobble = left < 2 ? sin(millis() / 35) * 5 * k : 0;
  const pop = map(millis() - gotItAt, 0, 300, 1.4, 1, true);
  drawPotato(width / 2 + wobble, height * 0.34, min(width, height * 0.5) * 0.62 * pop, heat);

  noStroke();
  fill(255);
  textStyle(BOLD);
  textSize(110 * k);
  centreLines(left.toFixed(1), height * 0.68, width, 100 * k);
  textSize(36 * k);
  const how = hasRealTilt ? 'Shake to throw!' : 'Press space to throw!';
  centreLines(millis() - threwAt < 700 ? 'Thrown!' : how, height * 0.78, width * 0.9, 44 * k);
  textStyle(NORMAL);
}

// someone else has it
function drawWatching(r) {
  background(20);
  const who = nameOfHolder(r.holder);
  fill(255);
  noStroke();
  textStyle(BOLD);
  fitNameText(who, 90 * k, width * 0.9);
  centreLines(who, height * 0.36, width, 10);
  textStyle(NORMAL);
  fill('#cfcfcf');
  textSize(30 * k);
  centreLines('has the potato', height * 0.44, width * 0.9, 40 * k);
  fill('#9a9a9a');
  textSize(22 * k);
  let line = 'Keep your phone ready.\nIt could come to you next.';
  if (millis() - threwAt < 1500 && millis() - threwAt > 0) {
    line = 'You threw it!';
  }
  centreLines(line, height * 0.6, width * 0.85, 30 * k);
}

function drawBurned(r) {
  const me_ = r.burnedId === shareClientId;
  background(me_ ? color('#b3261e') : color(20));
  noStroke();
  fill(255);
  textStyle(BOLD);
  if (me_) {
    textSize(60 * k);
    centreLines('You got burned', height * 0.34, width * 0.9, 70 * k);
    textStyle(NORMAL);
    textSize(26 * k);
    centreLines('A new round starts soon.', height * 0.56, width * 0.9, 34 * k);
  } else {
    fitNameText(r.burnedName, 70 * k, width * 0.9);
    centreLines(r.burnedName, height * 0.34, width, 10);
    textStyle(NORMAL);
    fill('#cfcfcf');
    textSize(30 * k);
    centreLines('got burned', height * 0.43, width * 0.9, 40 * k);
  }
  textStyle(NORMAL);
}

// the name of whoever holds the potato. it may be this phone's own name
function nameOfHolder(id) {
  for (let i = 0; i < guests.length; i++) {
    if (guests[i].id === id) {
      return guests[i].name || 'Someone';
    }
  }
  return 'Someone';
}

function fitNameText(str, biggest, w) {
  let size = biggest;
  textSize(size);
  while (textWidth(str) > w && size > 18) {
    size -= 4;
    textSize(size);
  }
}

// a title and a smaller line under it, for the waiting screens
function drawWords(rows) {
  noStroke();
  fill(255);
  textStyle(BOLD);
  textSize(34 * k);
  let y = height * 0.2;
  for (let i = 0; i < rows.length; i++) {
    if (rows[i][1] === 0) {
      textStyle(NORMAL);
      fill('#9a9a9a');
      textSize(24 * k);
    }
    if (rows[i][0]) {
      const n = centreLines(rows[i][0], y, width * 0.86, 40 * k);
      y += n * 40 * k + 20 * k;
    }
  }
  textStyle(NORMAL);
}

function drawFooter() {
  noStroke();
  fill(255, 255, 255, 140);
  textSize(17 * k);
  centreLines('You are ' + myName, height - 68 * k, width * 0.9, 24 * k);
  centreLines(footerLine(), height - 40 * k, width * 0.9, 24 * k);
}

// a potato: a lumpy oval with a few dark eyes. heat is 0 for cool, 1 for about to burn
function drawPotato(x, y, size, heat) {
  push();
  translate(x, y);
  rotate(-23);
  noStroke();
  fill(lerpColor(color('#c99a5b'), color('#ffb199'), heat * 0.6));
  ellipse(0, 0, size * 1.25, size * 0.9);
  ellipse(-size * 0.2, size * 0.05, size * 0.8, size * 0.85);
  fill(0, 0, 0, 70);
  ellipse(-size * 0.2, -size * 0.08, size * 0.12, size * 0.08);
  ellipse(size * 0.15, size * 0.12, size * 0.1, size * 0.07);
  ellipse(size * 0.3, -size * 0.1, size * 0.09, size * 0.06);
  pop();
}
